input.new_string:
/* Sidebar: the current page and hovered items wear the same gradient
   (+ glow in dark), morphing in over 0.3s. Every link text is always
   gradient-clipped — at rest the stops resolve to the plain text
   color, so only hover/active reveal the colors; that is what lets
   the change transition. The .is-link tier is required — VitePress's
   own active-item rule carries it and would out-specify the
   transparent color, leaving only the glow visible. */
.VPSidebar .VPSidebarItem.is-link > .item .link > .text {
  --link-stop-1: var(--vp-c-text-2);
  --link-stop-2: var(--vp-c-text-2);
  --link-stop-3: var(--vp-c-text-2);
  background: linear-gradient(
    165deg,
    var(--link-stop-1) 10%,
    var(--link-stop-2) 45%,
    var(--link-stop-3) 95%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  transition:
    --link-stop-1 0.3s ease,
    --link-stop-2 0.3s ease,
    --link-stop-3 0.3s ease,
    filter 0.3s ease;
}
.VPSidebar .VPSidebarItem.is-link.is-active > .item .link > .text,
.VPSidebar .VPSidebarItem.is-link > .item .link:hover > .text {
  --link-stop-1: #a78bfa;
  --link-stop-2: #818cf8;
  --link-stop-3: #22d3ee;
}
.dark .VPSidebar .VPSidebarItem.is-link.is-active > .item .link > .text,
.dark .VPSidebar .VPSidebarItem.is-link > .item .link:hover > .text {
  filter: drop-shadow(0 0 6px rgba(129, 140, 248, 0.3));
}

