.blog-card .go,
.VPSidebar .VPSidebarItem.is-link > .item .link > .text,
.VPNavBar .VPNavBarMenuLink,
.VPDocAsideOutline .outline-link,
.VPDocFooter .pager-link .title {
  background: linear-gradient(
    155deg,
    var(--link-stop-1) 10%,
    var(--link-stop-2) 45%,
    var(--link-stop-3) 95%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: var(--ivue-link-shadow);
  transition:
    --link-stop-1 0.3s ease,
    --link-stop-2 0.3s ease,
    --link-stop-3 0.3s ease,
    text-decoration-color 0.3s ease,
    transform 0.18s ease;
}

/* ALWAYS-ON: rest = the gradient */
.vp-doc :is(p, li, td) > a:not([class]):not(:has(code)),
.vp-doc :is(p, li, td) > strong > a:not([class]):not(:has(code)),
.vp-doc :is(p, li, td) a:not([class]) > code,
a.feature-inline-link,
.ix-start .go,
.blog-card .go {
  --link-stop-1: var(--ivue-link-1);
  --link-stop-2: var(--ivue-link-2);
  --link-stop-3: var(--ivue-link-3);
}
/* …hover = the monotonic highlight family */
.vp-doc :is(p, li, td) > a:not([class]):not(:has(code)):hover,
.vp-doc :is(p, li, td) > strong > a:not([class]):not(:has(code)):hover,
.vp-doc :is(p, li, td) a:not([class]):hover > code,
