await (async (page) => { const out = {}; await page.setViewportSize({ width: 1440, height: 950 }); await page.goto('http://localhost:5174/guide/computed-watch', { waitUntil: 'networkidle' }); await page.evaluate(() => document.documentElement.classList.add('dark')); await page.waitForTimeout(500); const probe = sel => page.evaluate(s => { const el = document.querySelector(s); if (!el) return 'MISSING'; const cs = getComputedStyle(el); return { color: cs.color, clip: (cs.webkitBackgroundClip || cs.backgroundClip), stop1: cs.getPropertyValue('--link-stop-1').trim() }; }, sel);
