async (page) => { const out = {}; await page.setViewportSize({ width: 1440, height: 950 }); await page.goto('http://localhost:4390/ivue/guide/computed-watch.html', { waitUntil: 'networkidle' }); await page.waitForTimeout(600);
// check @property survived minification
out.propertyRule = await page.evaluate(() => { for (const sheet of document.styleSheets) { try { for (const r of sheet.cssRules) { if (r instanceof CSSPropertyRule) return r.name; } } catch(e){} } return 'MISSING'; });
// nav hover: real mouse
const nav = await page.$('.VPNavBar .VPNavBarMenuLink'); const nb = await nav.boundingBox(); await page.mouse.move(nb.x + nb.width/2, nb.y + nb.height/2); await page.waitForTimeout(450);
out.navHover = await page.evaluate(() => { const el = document.querySelector('.VPNavBar .VPNavBarMenuLink:hover'); if (!el) return 'not hovered'; const cs = getComputedStyle(el); return { color: cs.color, clip: cs.webkitBackgroundClip || cs.backgroundClip, stop1: cs.getPropertyValue('--link-stop-1').trim(), bg: cs.backgroundImage.slice(0, 45) }; });
// sidebar hover: real mouse
const sb = (await page.$$('.VPSidebar .VPSidebarItem.is-link .link'))[4]; const sbb = await sb.boundingBox(); await page.mouse.move(sbb.x + sbb.width/2, sbb.y + sbb.height/2); await page.waitForTimeout(450);
out.sidebarHover = await page.evaluate(() => { const t = document.querySelector('.VPSidebar .link:hover .text'); if (!t) return 'not hovered'; const cs = getComputedStyle(t); return { color: cs.color, stop1: cs.getPropertyValue('--link-stop-1').trim() }; });
// button press: homepage hero CTA + start card, mouse down held
await page.goto('http://localhost:4390/ivue/', { waitUntil: 'networkidle' }); await page.waitForTimeout(500);
const cta = await page.$('.ix-standard-hero__cta'); const cb = await cta.boundingBox(); await page.mouse.move(cb.x + cb.width/2, cb.y + cb.height/2); await page.mouse.down(); await page.waitForTimeout(250);
out.ctaActive = await page.evaluate(() => getComputedStyle(document.querySelector('.ix-standard-hero__cta:active') || document.body).transform);
await page.mouse.up();
const card = await page.$('.ix-start a'); const kb = await card.boundingBox(); await page.mouse.move(kb.x + kb.width/2, kb.y + kb.height/2); await page.mouse.down(); await page.waitForTimeout(250);
out.cardActive = await page.evaluate(() => { const el = document.querySelector('.ix-start a:active'); return el ? getComputedStyle(el).transform : 'no active match'; });
await page.mouse.up();
return out; }

